import Foundation
import XCTest
@testable import MacScope

/// FEAT_PAuth_LR, FEAT_MOPS and FEAT_THE decode and disassembly text, checked against the local
/// Apple toolchain. The fixtures in `GoldenFixtures/arm64-feature-vectors/` are generated by
/// `Scripts/arm64_golden/generate_arm64_feature_vectors.py`: every word is assembled by
/// `xcrun clang` and its text is `xcrun llvm-objdump` output, so nothing here is hand-encoded.
/// `boundary.tsv` holds single-bit-flip neighbours and a register-edge sweep, which pin the
/// disambiguation against LDAPUR/STLUR (FEAT_LRCPC2) in the shared 0x19/0x59/0x99/0xd9 space.
final class ARM64FeatureFamilyGoldenTests: XCTestCase {
    private struct Row {
        let address: UInt64
        let word: UInt32
        let mnemonic: String
        let operands: String
        let family: String
        let source: String
    }

    private static let fixtureDirectory = TestSourceRoot.fileURL(#filePath)
        .deletingLastPathComponent()
        .appendingPathComponent("GoldenFixtures/arm64-feature-vectors")

    /// PC-relative label forms whose operand is an absolute address. MacScope renders addresses
    /// with `hexAddress` (16 digits) where objdump prints the minimal hex, so these compare numerically.
    private static let labelMnemonics: Set<String> = ["autiasppc", "autibsppc", "retaasppc", "retabsppc"]

    private static let lrcpcMnemonics: Set<String> = [
        "stlurb", "ldapurb", "ldapursb", "stlurh", "ldapurh", "ldapursh",
        "stlur", "ldapur", "ldapursw",
    ]

    /// Every mnemonic the three families define (plus the FEAT_PAuth_LR *171615 forms that share
    /// the PAuth_LR data-processing group, and the FEAT_D128 RCW pair forms that share the THE space).
    private static let expectedFamilyMnemonics: Set<String> = {
        var names: Set<String> = [
            "paciasppc", "pacibsppc", "pacnbiasppc", "pacnbibsppc",
            "pacia171615", "pacib171615", "autia171615", "autib171615",
            "autiasppc", "autibsppc", "autiasppcr", "autibsppcr",
            "retaasppc", "retabsppc", "retaasppcr", "retabsppcr", "pacm",
        ]
        let stages = ["p", "m", "e"]
        for base in ["cpyf", "cpy"] {
            for stage in stages {
                for read in ["", "wt", "rt", "t"] {
                    for write in ["", "wn", "rn", "n"] { names.insert(base + stage + read + write) }
                }
            }
        }
        for base in ["set", "setg"] {
            for stage in stages {
                for option in ["", "t", "n", "tn"] { names.insert(base + stage + option) }
            }
        }
        for prefix in ["rcw", "rcws"] {
            for operation in ["cas", "casp", "swp", "clr", "set", "swpp", "clrp", "setp"] {
                for ordering in ["", "a", "al", "l"] { names.insert(prefix + operation + ordering) }
            }
        }
        return names
    }()

    private static func table(_ name: String) throws -> [[String]] {
        let text = try String(contentsOf: fixtureDirectory.appendingPathComponent(name), encoding: .utf8)
        return text.split(separator: "\n", omittingEmptySubsequences: true)
            .filter { !$0.hasPrefix("#") }
            .map { $0.components(separatedBy: "\t") }
    }

    private static func hex<T: FixedWidthInteger>(_ text: String, as type: T.Type) throws -> T {
        let digits = text.hasPrefix("0x") ? String(text.dropFirst(2)) : text
        return try XCTUnwrap(T(digits, radix: 16), "bad hex \(text)")
    }

    private static func vectors() throws -> [Row] {
        try table("vectors.tsv").map { fields in
            XCTAssertEqual(fields.count, 6, "malformed vectors.tsv row \(fields)")
            return Row(
                address: try hex(fields[1], as: UInt64.self),
                word: try hex(fields[2], as: UInt32.self),
                mnemonic: fields[3],
                operands: fields[4],
                family: fields[0],
                source: fields[5]
            )
        }
    }

    private static func boundary() throws -> [Row] {
        try table("boundary.tsv").map { fields in
            XCTAssertTrue(fields.count == 3 || fields.count == 4, "malformed boundary.tsv row \(fields)")
            return Row(
                address: try hex(fields[0], as: UInt64.self),
                word: try hex(fields[1], as: UInt32.self),
                mnemonic: fields[2],
                operands: fields.count > 3 ? fields[3] : "",
                family: "boundary",
                source: fields[1]
            )
        }
    }

    private func decode(_ word: UInt32, at address: UInt64) -> DecodedInstruction {
        let data = Data([
            UInt8(word & 0xff), UInt8((word >> 8) & 0xff), UInt8((word >> 16) & 0xff), UInt8((word >> 24) & 0xff),
        ])
        return ARM64Decoder().decode(data, baseAddress: address, maxInstructionCount: 1)[0]
    }

    /// Rewrites every numeric token (`#5`, `#0x5`, `0x68`, `0x0000000000000068`) to decimal so
    /// MacScope's existing immediate/address spelling compares by value with objdump's.
    private static func numericallyNormalized(_ text: String) -> String {
        let pattern = try! NSRegularExpression(pattern: #"(?<![A-Za-z0-9_])(-?)(0x[0-9a-fA-F]+|[0-9]+)(?![A-Za-z0-9_])"#)
        var result = text
        for match in pattern.matches(in: text, range: NSRange(text.startIndex..., in: text)).reversed() {
            guard let whole = Range(match.range, in: text),
                  let sign = Range(match.range(at: 1), in: text),
                  let digits = Range(match.range(at: 2), in: text) else { continue }
            let token = String(text[digits])
            let value = token.hasPrefix("0x") ? UInt64(token.dropFirst(2), radix: 16) : UInt64(token)
            guard let value else { continue }
            result.replaceSubrange(whole, with: "\(text[sign])\(value)")
        }
        return result
    }

    func testFixtureCoversEveryMnemonicOfTheThreeFamilies() throws {
        let rows = try Self.vectors()
        let covered = Set(rows.filter { $0.family != "lrcpc" }.map(\.mnemonic))
        XCTAssertEqual(covered.subtracting(Self.expectedFamilyMnemonics), [], "fixture has unexpected mnemonics")
        XCTAssertEqual(Self.expectedFamilyMnemonics.subtracting(covered), [], "fixture misses mnemonics")
        XCTAssertEqual(Self.expectedFamilyMnemonics.count, 17 + 120 + 64)
        // Both forms of the PAuth_LR authenticate/return instructions are present.
        XCTAssertTrue(rows.contains { $0.mnemonic == "autiasppc" } && rows.contains { $0.mnemonic == "autiasppcr" })
        XCTAssertTrue(rows.contains { $0.mnemonic == "retabsppc" } && rows.contains { $0.mnemonic == "retabsppcr" })
    }

    func testReferenceEncodings() {
        XCTAssertEqual(text(decode(0xdac1_a7fe, at: 0)), "pacibsppc")
        XCTAssertEqual(text(decode(0x1901_0440, at: 0)), "cpyfp [x0]!, [x1]!, x2!")
        XCTAssertEqual(text(decode(0x1920_0841, at: 0)), "rcwcas x0, x1, [x2]")
    }

    func testEveryGoldenVectorMatchesObjdumpText() throws {
        let rows = try Self.vectors()
        XCTAssertGreaterThan(rows.count, 300)
        for row in rows {
            let decoded = decode(row.word, at: row.address)
            let context = "\(String(format: "%08x", row.word)) @\(String(row.address, radix: 16)) [\(row.source)]"
            XCTAssertEqual(decoded.mnemonic, row.mnemonic, context)
            if Self.labelMnemonics.contains(row.mnemonic) {
                XCTAssertEqual(UInt64(decoded.operands.dropFirst(2), radix: 16), try Self.hex(row.operands, as: UInt64.self), context)
                XCTAssertNil(decoded.branchTarget, "PAC modifier label is not a branch target: \(context)")
            } else {
                XCTAssertEqual(decoded.operands, row.operands, context)
            }
        }
    }

    func testPAuthLRReturnsAreReturnFlow() throws {
        for mnemonic in ["retaasppc", "retabsppc", "retaasppcr", "retabsppcr"] {
            XCTAssertEqual(ARM64Decoder.flow(for: mnemonic), .return, mnemonic)
        }
        // pacm is hint #39 only with op1=0b011; op1=0b001 is MSR to S0_1_C2_C4_7, not a hint.
        XCTAssertEqual(text(decode(0xd503_24ff, at: 0)), "pacm")
        XCTAssertNotEqual(decode(0xd501_24ff, at: 0).mnemonic, "pacm")
        // RETAA/RETAB (Rm=31) are unchanged by the RETAASPPCR hook.
        XCTAssertEqual(text(decode(0xd65f_0bff, at: 0)), "retaa")
        XCTAssertEqual(text(decode(0xd65f_0fff, at: 0)), "retab")
        // A label that would precede address 0 is reported, not wrapped.
        let underflow = decode(0x5500_003f, at: 0)
        XCTAssertEqual(underflow.mnemonic, "retaasppc")
        XCTAssertEqual(underflow.operands, "<address overflow>")
    }

    /// LDAPUR/STLUR (FEAT_LRCPC2) share bits[29:24]=011001 with MOPS (bits[11:10]=01) and the THE
    /// CAS group (bit21=1). Their decode must be exactly objdump's, as it was before these families.
    func testLDAPURAndSTLURDecodeUnchanged() throws {
        let rows = try Self.vectors().filter { $0.family == "lrcpc" }
        XCTAssertEqual(rows.count, 52)
        for row in rows {
            let decoded = decode(row.word, at: row.address)
            XCTAssertEqual(text(decoded), "\(row.mnemonic) \(row.operands)", "\(String(format: "%08x", row.word)) [\(row.source)]")
        }
        // The pre-existing hand-checked LRCPC words (ARM64DecodeTailOracleTests) are still byte-for-byte the same.
        XCTAssertEqual(text(decode(0xd95f_0128, at: 0)), "ldapur x8, [x9, #-0x10]")
        XCTAssertEqual(text(decode(0x195f_01ac, at: 0)), "ldapurb w12, [x13, #-0x10]")
        XCTAssertEqual(text(decode(0x5941_01ee, at: 0)), "ldapurh w14, [x15, #0x10]")
        XCTAssertEqual(text(decode(0x191f_03fe, at: 0)), "stlurb w30, [sp, #-0x10]")
        XCTAssertEqual(text(decode(0x5901_0020, at: 0)), "stlurh w0, [x1, #0x10]")
        XCTAssertEqual(text(decode(0x9901_43bc, at: 0)), "stlur w28, [x29, #0x14]")
    }

    /// Bit-flip and register-edge neighbours: where objdump decodes a new-family or LDAPUR/STLUR
    /// instruction, MacScope must render the same text (numbers compared by value); where objdump
    /// decodes anything else or rejects the word, MacScope must not claim a new-family mnemonic.
    func testBoundaryNeighboursMatchObjdump() throws {
        let rows = try Self.boundary()
        XCTAssertGreaterThan(rows.count, 3000)
        var exact = 0, lrcpc = 0, rejected = 0
        for row in rows {
            let decoded = decode(row.word, at: row.address)
            let context = "\(String(format: "%08x", row.word)): objdump `\(row.mnemonic) \(row.operands)`, MacScope `\(text(decoded))`"
            if Self.labelMnemonics.contains(row.mnemonic), decoded.operands == "<address overflow>" {
                // objdump wraps a label below address 0 modulo 2^64; MacScope reports the
                // underflow instead (the same policy as branch targets).
                XCTAssertEqual(decoded.mnemonic, row.mnemonic, context)
                XCTAssertGreaterThan(UInt64((row.word >> 5) & 0xffff) << 2, row.address, context)
                exact += 1
            } else if Self.expectedFamilyMnemonics.contains(row.mnemonic) || Self.lrcpcMnemonics.contains(row.mnemonic) {
                XCTAssertEqual(decoded.mnemonic, row.mnemonic, context)
                XCTAssertEqual(Self.numericallyNormalized(decoded.operands), Self.numericallyNormalized(row.operands), context)
                if Self.lrcpcMnemonics.contains(row.mnemonic) { lrcpc += 1 } else { exact += 1 }
            } else {
                XCTAssertFalse(Self.expectedFamilyMnemonics.contains(decoded.mnemonic), context)
                rejected += 1
            }
        }
        XCTAssertGreaterThan(exact, 1000)
        XCTAssertGreaterThan(lrcpc, 50)
        XCTAssertGreaterThan(rejected, 1000)
    }

    private func text(_ decoded: DecodedInstruction) -> String {
        decoded.operands.isEmpty ? decoded.mnemonic : "\(decoded.mnemonic) \(decoded.operands)"
    }
}
